import unittest
from checkout import total
from preview import preview_total
from csv_import import parse_row

class Bookings(unittest.TestCase):
    def test_member_group(self):
        booking = {"seats": 5, "price": 10, "member": True}
        self.assertEqual(total(booking), 42.75)
        self.assertEqual(preview_total(booking), 42.75)

    def test_saved_export(self):
        self.assertEqual(parse_row({"quantity": "2", "unit_price": "12"}), {"seats": 2, "price": 12.0})

