import unittest
from board import render_board

class Store:
    def all_labels(self):
        return [{"id": 1, "name": "One"}]

class Board(unittest.TestCase):
    def test_label_and_title(self):
        self.assertEqual(render_board([{"id": 2, "title": " A ", "label_id": 1}], Store()), [{"id": 2, "title": "A", "label": "One"}])
    def test_missing_label(self):
        self.assertEqual(render_board([{"id": 2, "title": "A", "label_id": 99}], Store())[0]["label"], "Unknown")
